"""SFI team name → canonical team ID mapping.

543 teams across 33 prediction leagues.
108 manual overrides for SFI abbreviations (Man City → MANCHESTER_CITY, etc.).
Remaining entries use build_team_id() (SCREAMING_SNAKE).
Generated from 7 sample dates across 2024-2025 seasons.
"""

from __future__ import annotations

from unified_api_contracts.canonical.domain.sports.canonical_ids import build_team_id

_SFI_INDEX: dict[str, str] | None = None


def _sfi_name_index() -> dict[str, str]:
    """Build a case-insensitive index on first access."""
    global _SFI_INDEX
    if _SFI_INDEX is None:
        _SFI_INDEX = {k.lower().strip(): v for k, v in SFI_TEAM_NAME_TO_CANONICAL.items()}
    return _SFI_INDEX


def resolve_sfi_team(team_name: str) -> str:
    """Resolve SFI team name to canonical team ID.

    Falls back to build_team_id() if no mapping found.
    """
    canonical = _sfi_name_index().get(team_name.lower().strip())
    return canonical if canonical else build_team_id(team_name)


